(7595353, 1225602, 189992, '<td valign="top">Great pic.  I don''t understand how this fits the "Abandoned," but I love the pic.</td>', 'Great pic.  I don''t understand how this fits the "Abandoned," but I love the pic.', '2018-09-07 10:14:50.000000', NULL, 1),
